dataprocessscript.script:
import java.util.Properties;
import java.io.InputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.AtomicMoveNotSupportedException;
import groovy.json.JsonSlurper;
import groovy.json.JsonOutput;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);
    String control = props.getProperty("document.dynamic.userdefined.DDP_P01_CONTROL_FILE", "");
    String sourceRel = props.getProperty("document.dynamic.userdefined.DDP_P01_SOURCE_PATH", "");
    String base = control.endsWith(".ready.json") ? control.substring(0, control.length() - 11) : control;
    String processingName = base + ".processing.json";
    String committedName = base + ".committed.json";
    String quarantineName = base + ".quarantine.json";

    File ready = new File("D:\\BoomiLab\\Project01\\work\\ready", control);
    File processing = new File("D:\\BoomiLab\\Project01\\work\\processing", processingName);
    File committed = new File("D:\\BoomiLab\\Project01\\work\\committed", committedName);
    File source = new File("D:\\BoomiLab\\Project01\\source\\chunks", sourceRel);
    String status = "";

    if (committed.exists()) {
        status = "SKIP_COMMITTED";
    }
    else if (ready.exists() && !processing.exists()) {
        try { Files.move(ready.toPath(), processing.toPath(), StandardCopyOption.ATOMIC_MOVE); }
        catch (AtomicMoveNotSupportedException ex) { Files.move(ready.toPath(), processing.toPath()); }
        status = "CLAIMED";
    }
    else if (!ready.exists() && processing.exists()) {
        long ageMs = System.currentTimeMillis() - processing.lastModified();
        if (ageMs > 1800000L) {
            try { Files.move(processing.toPath(), ready.toPath(), StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException ex) { Files.move(processing.toPath(), ready.toPath()); }
            try { Files.move(ready.toPath(), processing.toPath(), StandardCopyOption.ATOMIC_MOVE); }
            catch (AtomicMoveNotSupportedException ex) { Files.move(ready.toPath(), processing.toPath()); }
            status = "CLAIMED";
            props.setProperty("document.dynamic.userdefined.DDP_P01_RECOVERED_STALE", "true");
        }
        else status = "ALREADY_PROCESSING";
    }
    else if (ready.exists() && processing.exists()) status = "STATE_COLLISION";
    else status = "MISSING_READY";

    if ("CLAIMED".equals(status) && processing.exists()) {
        try {
            def state = new JsonSlurper().parse(processing);
            state.status = "PROCESSING";
            state.controlFileName = processingName;
            state.processingStartedEpochMs = System.currentTimeMillis();
            String stateJson = JsonOutput.prettyPrint(JsonOutput.toJson(state));
            FileOutputStream fos = new FileOutputStream(processing, false);
            try { fos.write(stateJson.getBytes("UTF-8")); } finally { fos.close(); }
        }
        catch (Exception ex) {
            status = "CLAIM_METADATA_WRITE_FAILED";
            props.setProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", ex.getClass().getSimpleName() + ": " + ex.getMessage());
        }
    }

    props.setProperty("document.dynamic.userdefined.DDP_P01_PROCESSING_FILE", processingName);
    props.setProperty("document.dynamic.userdefined.DDP_P01_COMMITTED_FILE", committedName);
    props.setProperty("document.dynamic.userdefined.DDP_P01_QUARANTINE_FILE", quarantineName);
    props.setProperty("document.dynamic.userdefined.DDP_P01_STREAM_FILE", source.getAbsolutePath());
    props.setProperty("document.dynamic.userdefined.DDP_P01_CLAIM_STATUS", status);
    dataContext.storeStream(is, props);
}

import java.util.Properties;
import java.io.InputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.AtomicMoveNotSupportedException;
import groovy.json.JsonSlurper;
import groovy.json.JsonOutput;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);
    File processing = new File("D:\\BoomiLab\\Project01\\work\\processing", props.getProperty("document.dynamic.userdefined.DDP_P01_PROCESSING_FILE", ""));
    File committed = new File("D:\\BoomiLab\\Project01\\work\\committed", props.getProperty("document.dynamic.userdefined.DDP_P01_COMMITTED_FILE", ""));

    if (committed.exists()) {
        props.setProperty("document.dynamic.userdefined.DDP_P01_COMMIT_STATUS", "COMMITTED");
    }
    else if (!processing.exists()) {
        props.setProperty("document.dynamic.userdefined.DDP_P01_COMMIT_STATUS", "MISSING_PROCESSING");
    }
    else {
        def state = new JsonSlurper().parse(processing);
        state.status = "COMMITTED";
        state.controlFileName = committed.getName();
        state.validationStatus = props.getProperty("document.dynamic.userdefined.DDP_P01_VALIDATION_STATUS", "");
        state.actualBytes = props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_BYTES", "");
        state.actualSha256 = props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_SHA256", "");
        state.committedEpochMs = System.currentTimeMillis();
        String stateJson = JsonOutput.prettyPrint(JsonOutput.toJson(state));
        FileOutputStream fos = new FileOutputStream(processing, false);
        try { fos.write(stateJson.getBytes("UTF-8")); } finally { fos.close(); }

        try { Files.move(processing.toPath(), committed.toPath(), StandardCopyOption.ATOMIC_MOVE); }
        catch (AtomicMoveNotSupportedException ex) { Files.move(processing.toPath(), committed.toPath()); }
        props.setProperty("document.dynamic.userdefined.DDP_P01_COMMIT_STATUS", "COMMITTED");
    }

    dataContext.storeStream(is, props);
}

import java.util.Properties;
import java.io.InputStream;
import java.io.File;
import java.io.FileOutputStream;
import java.nio.file.Files;
import java.nio.file.StandardCopyOption;
import java.nio.file.AtomicMoveNotSupportedException;
import groovy.json.JsonSlurper;
import groovy.json.JsonOutput;

for (int i = 0; i < dataContext.getDataCount(); i++) {
    InputStream is = dataContext.getStream(i);
    Properties props = dataContext.getProperties(i);
    File processing = new File("D:\\BoomiLab\\Project01\\work\\processing", props.getProperty("document.dynamic.userdefined.DDP_P01_PROCESSING_FILE", ""));
    File quarantine = new File("D:\\BoomiLab\\Project01\\work\\quarantine", props.getProperty("document.dynamic.userdefined.DDP_P01_QUARANTINE_FILE", ""));

    if (processing.exists() && !quarantine.exists()) {
        try {
            def state = new JsonSlurper().parse(processing);
            state.status = "QUARANTINED";
            state.controlFileName = quarantine.getName();
            state.failureReason = props.getProperty("document.dynamic.userdefined.DDP_P01_FAILURE_REASON", "INTEGRITY_VALIDATION_FAILED");
            state.actualBytes = props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_BYTES", "");
            state.actualSha256 = props.getProperty("document.dynamic.userdefined.DDP_P01_ACTUAL_SHA256", "");
            state.quarantinedEpochMs = System.currentTimeMillis();
            String stateJson = JsonOutput.prettyPrint(JsonOutput.toJson(state));
            FileOutputStream fos = new FileOutputStream(processing, false);
            try { fos.write(stateJson.getBytes("UTF-8")); } finally { fos.close(); }
        }
        catch (Exception ignored) {}

        try { Files.move(processing.toPath(), quarantine.toPath(), StandardCopyOption.ATOMIC_MOVE); }
        catch (AtomicMoveNotSupportedException ex) { Files.move(processing.toPath(), quarantine.toPath()); }
    }
    props.setProperty("document.dynamic.userdefined.DDP_P01_QUARANTINE_STATUS", quarantine.exists() ? "QUARANTINED" : "QUARANTINE_MOVE_FAILED");
    dataContext.storeStream(is, props);
}
